        if new_penalty > 0.0 {
            score += new_penalty;
        }
    }

    // --- Exact fit bonus ---
    if post_residual == 0 {
        score -= 30.0;
    }

    // --- Small residual that still holds the item ---
    if post_residual <= 6 && item_size <= post_residual {
        score -= 10.0;
    }

    // --- Residual much smaller than the item size ---
    if post_residual < item_size / 4 {
        score -= 8.0;
    }

    // --- Non‑linear deviation from mean residual ---
    score += 0.5 * (post_f - mean_residual).abs();

    // --- Squared residual penalty (dead space) ---
    score += 0.015 * post_f * post_f;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;
    let bin_cap_f = bin_capacity as f64;
    let post_ratio = post_residual as f64 / bin_cap_f;
    let mean_ratio = mean_residual / bin_cap_f;
    let total_f = total_items as f64;
    let progress = step_index as f64 / total_f;

    // Dynamic residual penalty that grows as the stream progresses
    let residual_weight = 50.0 + 20.0 * progress;
    score += residual_weight * post_ratio;

    // Reward closeness to the mean residual across all open bins
    score -= 40.0 * (post_ratio - mean_ratio).abs();

    // Strong penalty if this is the sole fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count <= 3 {
        score -= 10.0;
    }

    // Look‑ahead: penalise if the next item cannot fit, otherwise reward
    if next_item_size > post_residual {
        score += 5.0 * (next_item_size - post_residual) as f64;
    } else {
        score -= 5.0 * ((post_residual - next_item_size) as f64 / bin_cap_f);
    }

    // Encourage tighter packing as we near the end of the stream
    score += 15.0 * progress * progress;

    // Penalise having many open bins
    score += 2.0 * open_bins_count as f64;

    // New‑bin candidate: high penalty for small items, low penalty for large items
    if bin_residual == bin_capacity {
        let new_bin_penalty =
            (30.0 * (1.0 - (item_size as f64 / bin_cap_f))).max(0.0);
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Quick guard – if the bin cannot actually hold the item, return a huge penalty.
    if bin_residual < item_size {
        return 1e9;
    }

    let bin_cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let item_f = item_size as f64;
    let next_f = next_item_size as f64;
    let remaining_before = bin_residual as f64;

    let post_ratio = post_f / bin_cap_f;
    let mean_ratio = mean_residual / bin_cap_f;
    let item_ratio = item_f / bin_cap_f;

    // Base score from the residual space that will remain.
    let mut score = 0.5 * post_f;

    // Penalize large residual fractions – we want tighter packing.
    score += 15.0 * post_ratio;

    // Reward closeness to the current mean residual.
    let mean_diff = (post_ratio - mean_ratio).abs();
    score -= 12.0 * mean_diff;

    // Extra penalty if the residual is much larger than the mean.
    if post_ratio > mean_ratio * 1.2 {
        score += 8.0 * (post_ratio - mean_ratio);
    }

    // If this is the only bin that can fit the item, give a bonus.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Look‑ahead penalty if the next item will not fit in the residual.
    if next_f > post_f {
        score += 6.0 * (next_f - post_f);
    } else if next_f * 2.0 <= post_f {
        // Small next item fits comfortably – slight reward.
        score -= 4.0;
    }

    // Encourage using bins later in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += 3.0 * progress;

    // Penalise the number of open bins to discourage keeping many half‑filled bins.
    score += 0.15 * (open_bins_count as f64).sqrt();

    // New‑bin penalty: less severe for items that almost fill the bin.
    if bin_residual == bin_capacity {
        let new_pen = 10.0 - 5.0 * item_ratio;
        if new_pen > 0.0 {
            score += new_pen;
        }
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Bonus for a very small residual that could still accommodate the next item.
    if post_residual <= 8 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Reward when the residual is significantly smaller than the item.
    if post_residual < item_size / 4 {
        score -= 6.0;
    }

    // Non‑linear penalty for deviation from the mean residual.
    score += 0.3 * (post_f - mean_residual).abs();

    // Penalise squared residual to reduce dead space.
    score += 0.02 * post_f * post_f;

    // Extra reward if residual is noticeably below the mean.
    let mean_minus_05 = mean_residual - 0.05 * bin_cap_f;
    if post_f < mean_minus_05 {
        score -= 2.5;
    }

    // Minor penalty if the item is large relative to the residual.
    if item_size > post_residual / 2 {
        score += 1.5 * (item_f - post_f);
    }

    // Fit factor: reward placements that use the bin almost exactly.
    let fit_factor = item_f / remaining_before;
    if fit_factor > 0.9 && fit_factor < 1.1 {
        score -= 4.0;
    }

    score
}
